export const HOA12_CHUONG1_HANDBOOK = [{"title": "1. Khái Niệm & Công Thức Chung Của Ester", "icon": "🧪", "content": ["Khi thay nhóm –OH ở nhóm carboxyl của carboxylic acid bằng nhóm –OR' thì được ester.", "Ester no, đơn chức, mạch hở: C<sub>n</sub>H<sub>2n</sub>O<sub>2</sub> (n ≥ 2).", "Ester không no, đơn chức chứa 1 nối đôi C=C mạch hở: C<sub>n</sub>H<sub>2n-2</sub>O<sub>2</sub> (n ≥ 3).", "Độ bất bão hoà k = (2C + 2 - H)/2. Với ester no đơn chức: k = 1 (1 liên kết C=O)."]}, {"title": "2. Quy Tắc Gọi Tên Ester Theo IUPAC 2024 - 2025", "icon": "🏷️", "content": ["Công thức gọi tên chuẩn quốc tế: Tên gốc hydrocarbon R' + Tên gốc carboxylate RCOO- + 'ate'.", "HCOOCH<sub>3</sub>: methyl formate (hoặc methyl methanoate).", "CH<sub>3</sub>COOC<sub>2</sub>H<sub>5</sub>: ethyl acetate (hoặc ethyl ethanoate).", "CH<sub>2</sub>=CHCOOCH<sub>3</sub>: methyl acrylate (hoặc methyl propenoate).", "CH<sub>2</sub>=C(CH<sub>3</sub>)COOCH<sub>3</sub>: methyl methacrylate.", "CH<sub>3</sub>COOCH<sub>2</sub>C<sub>6</sub>H<sub>5</sub>: benzyl acetate (mùi thơm hoa nhài).", "CH<sub>3</sub>COOCH<sub>2</sub>CH<sub>2</sub>CH(CH<sub>3</sub>)<sub>2</sub>: isoamyl acetate (mùi chuối chín)."]}, {"title": "3. Tính Chất Vật Lý & Hóa Học Trọng Tâm", "icon": "⚡", "content": ["Nhiệt độ sôi: Acid > Alcohol > Ester > Hydrocarbon (do ester không tạo liên kết hydrogen liên phân tử).", "Độ tan: Ester rất ít tan trong nước, nhẹ hơn nước, nổi lên trên.", "Thủy phân trong môi trường acid (thuận nghịch): RCOOR' + H<sub>2</sub>O ⇌ RCOOH + R'OH (xúc tác H<sub>2</sub>SO<sub>4</sub> đặc, t°).", "Thủy phân trong môi trường kiềm (xà phòng hóa - một chiều): RCOOR' + NaOH → RCOONa + R'OH (đun nóng).", "Ester của phenol: RCOOC<sub>6</sub>H<sub>5</sub> + 2NaOH → RCOONa + C<sub>6</sub>H<sub>5</sub>ONa + H<sub>2</sub>O (tỉ lệ mol 1:2)."]}, {"title": "4. Chất Béo, Acid Béo Omega-3 & Omega-6", "icon": "🥑", "content": ["Chất béo (triglyceride) là triester của glycerol với các acid béo: (RCOO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub>.", "Palmitic acid: C<sub>15</sub>H<sub>31</sub>COOH (no, 16C, rắn). Trọng lượng phân tử M = 256.", "Stearic acid: C<sub>17</sub>H<sub>35</sub>COOH (no, 18C, rắn). Trọng lượng phân tử M = 284.", "Oleic acid: C<sub>17</sub>H<sub>33</sub>COOH (không no, 1 nối đôi cis ở C9, lỏng).", "Linoleic acid: C<sub>17</sub>H<sub>31</sub>COOH (không no, 2 nối đôi cis, acid béo omega-6 thiết yếu).", "α-Linolenic acid (ALA): C<sub>17</sub>H<sub>29</sub>COOH (không no, 3 nối đôi cis, acid béo omega-3 thiết yếu)."]}, {"title": "5. Xà Phòng & Chất Giặt Rửa Tổng Hợp", "icon": "🧼", "content": ["Xà phòng là hỗn hợp muối sodium hoặc potassium của các acid béo (thường là C15-C17).", "Chất giặt rửa tổng hợp: muối sodium của alkyl sulfate (ROSO<sub>3</sub>Na) hoặc alkylbenzenesulfonate (RC<sub>6</sub>H<sub>4</sub>SO<sub>3</sub>Na).", "Cơ chế tẩy rửa: Phân tử gồm 'đầu' ưa nước (hướng ra ngoài dung dịch) và 'đuôi' kị nước dài (gắn vào hạt dầu mỡ). Nhiều phân tử tụ lại thành hạt micelle hình cầu lơ lửng trong nước và bị rửa trôi.", "Nước cứng (chứa nhiều Ca<sup>2+</sup>, Mg<sup>2+</sup>): Làm kết tủa muối xà phòng ((RCOO)<sub>2</sub>Ca), mất tác dụng giặt rửa. Chất giặt rửa tổng hợp không bị kết tủa trong nước cứng."]}];

